/* C side of the Hirsel ABI v1 probes (crates/hirsel-llvm/tests/native.rs, `abi_program`).
 *
 * C calls every emitted entry through `call_<entry>`, a function of the physical signature
 * its FnAbi describes: the run context, then [environment], [caller destination], [result
 * pointer], then each declared parameter's slots, returning a u8 status. `entries.h`
 * (generated by `hirsel_llvm::c_call`) bridges each to the entry as emission lowers it, so
 * no prototype here restates the register-result rule. The object calls back into C twice:
 * HOST_SCALE is a Hirsel entry defined over `host_scale_body`, and scale_thunk is a closure entry
 * defined over `scale_body`, reached through a callable value (`hirsel_llvm::c_definition`).
 * `names.h` (generated) defines the layout facts the structs below must match. */
#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "hirsel_rt_v2.h"
#include "names.h"

typedef struct {
  __int128 a, b;
} Pair;

typedef struct __attribute__((packed)) {
  uint8_t a;
  uint64_t b;
  uint16_t c;
} Wire;

typedef struct {
  uint32_t tag;
  int64_t value;
} Opt;

_Static_assert(sizeof(Pair) == PAIR_SIZE && _Alignof(Pair) == PAIR_ALIGN, "Pair layout");
_Static_assert(offsetof(Pair, b) == PAIR_B, "Pair.b");
_Static_assert(sizeof(Wire) == WIRE_SIZE && offsetof(Wire, b) == WIRE_B && offsetof(Wire, c) == WIRE_C,
               "Wire layout");
_Static_assert(sizeof(Opt) == OPT_SIZE && offsetof(Opt, value) == OPT_VALUE, "Opt layout");
_Static_assert(sizeof(int64_t[4]) == ARR_SIZE, "Inline[i64, 4] layout");

typedef hirsel_rt_v2_ctx ctx_t;

/* The entry HOST_SCALE implements, of the ABI v1 signature `i64 -> i64`. Fails for a
 * negative argument. */
static uint8_t host_scale_body(ctx_t *ctx, void *out, int64_t x) {
  if (x < 0) return hirsel_rt_v2_failure_begin(ctx, 5, 50, 0x55, 0x55);
  int64_t r = x * 3;
  memcpy(out, &r, sizeof r);
  return 0;
}

/* The closure body: context, environment, the result, then the declared parameter. */
static uint8_t scale_body(ctx_t *ctx, void *environment, void *out, int64_t x) {
  int64_t k = *(const int64_t *)environment;
  if (x > 1000) return hirsel_rt_v2_failure_begin(ctx, 7, 70, 0x77, 0x77);
  int64_t r = x * k;
  memcpy(out, &r, sizeof r);
  return 0;
}

#include "entries.h"

static ctx_t *ctx;

static void bits(unsigned __int128 v) { printf("%016" PRIx64 "%016" PRIx64, (uint64_t)(v >> 64), (uint64_t)v); }

/* Prints `name ok`, then the caller prints the value; or `name fail kind rule site`. */
static int status(const char *name, uint8_t s) {
  printf("%s ", name);
  if (s == 0) {
    printf("ok ");
    return 1;
  }
  hirsel_rt_v2_failure f;
  if (s != 1 || !hirsel_rt_v2_failure_primary(ctx, &f)) {
    printf("bad status %u\n", (unsigned)s);
    return 0;
  }
  printf("fail %u %u %016" PRIx64 "\n", f.kind, f.rule, f.site);
  hirsel_rt_v2_failure_clear(ctx);
  return 0;
}

/* An integer result of `type`, read after the call. */
#define I64_CASE(name, type, entry, ...)                                  \
  do {                                                                    \
    type r_ = 0;                                                          \
    uint8_t s_ = entry(ctx, &r_, __VA_ARGS__);                            \
    if (status(name, s_)) printf("%" PRId64 "\n", (int64_t)r_);           \
  } while (0)
/* The call runs before its result is read: C leaves argument evaluation order unspecified. */
#define I128_CASE(name, call, result)        \
  do {                                       \
    uint8_t s_ = (call);                     \
    if (status(name, s_)) {                  \
      bits((unsigned __int128)(result));     \
      printf("\n");                          \
    }                                        \
  } while (0)

int main(void) {
  hirsel_rt_v2_config config;
  memset(&config, 0, sizeof config);
  config.abi_version = HIRSEL_RT_V2_ABI_VERSION;
  if (hirsel_rt_v2_ctx_create(&config, &ctx) != 0) {
    printf("no context\n");
    return 1;
  }
  __int128 w = 0;
  uint64_t u = 0;

  I64_CASE("inc 41", int64_t, call_inc, 41);
  I64_CASE("inc max", int64_t, call_inc, INT64_MAX);
  I64_CASE("twice_inc 40", int64_t, call_twice_inc, 40);
  I64_CASE("twice_inc max-1", int64_t, call_twice_inc, INT64_MAX - 1);
  I64_CASE("host_call 5", int64_t, call_host_call, 5);
  I64_CASE("host_call -1", int64_t, call_host_call, -1);
  I64_CASE("host_call max/3", int64_t, call_host_call, INT64_MAX / 3);

  __int128 big = (__int128)(((unsigned __int128)1 << 126));
  Pair p = {big, big - 1};
  I128_CASE("pair_sum 2^126+2^126-1", call_pair_sum(ctx, &w, &p), w);
  p.b = big;
  I128_CASE("pair_sum 2^126+2^126", call_pair_sum(ctx, &w, &p), w);
  p.a = -5;
  p.b = 7;
  I128_CASE("pair_take -5-7", call_pair_take(ctx, &w, &p), w);
  Pair made;
  memset(&made, 0xab, sizeof made);
  if (status("pair_make", call_pair_make(ctx, &made, -2, big))) {
    bits((unsigned __int128)made.a);
    printf(" ");
    bits((unsigned __int128)made.b);
    printf("\n");
  }

  /* A Wire at an odd address, so its u64 field is misaligned in memory too. */
  unsigned char buffer[1 + sizeof(Wire)];
  Wire wire = {9, 0x0102030405060708ull, 0xbeef};
  memcpy(buffer + 1, &wire, sizeof wire);
  uint8_t s = call_wire_value(ctx, &u, (const Wire *)(buffer + 1));
  if (status("wire_value", s)) printf("%016" PRIx64 "\n", u);
  wire.b = UINT64_MAX;
  memcpy(buffer + 1, &wire, sizeof wire);
  s = call_wire_value(ctx, &u, (const Wire *)(buffer + 1));
  if (status("wire_value max", s)) printf("%016" PRIx64 "\n", u);
  memset(buffer, 0xcd, sizeof buffer);
  if (status("wire_make", call_wire_make(ctx, NULL, (Wire *)(buffer + 1), 0xfe, 0x1122334455667788ull, 0x9988))) {
    Wire out;
    memcpy(&out, buffer + 1, sizeof out);
    printf("%02x %016" PRIx64 " %04x\n", out.a, out.b, out.c);
  }

  Opt some = {1, -77};
  I64_CASE("opt_get some", int64_t, call_opt_get, &some);
  Opt none = {0, 0};
  I64_CASE("opt_get none", int64_t, call_opt_get, &none);
  Opt built;
  memset(&built, 0xee, sizeof built);
  if (status("opt_some", call_opt_some(ctx, &built, 123))) printf("%u %" PRId64 "\n", built.tag, built.value);

  int64_t arr[4] = {10, 20, 30, 40};
  I64_CASE("arr_get 3", int64_t, call_arr_get, arr, 3);
  I64_CASE("arr_get 4", int64_t, call_arr_get, arr, 4);
  I64_CASE("arr_get max", int64_t, call_arr_get, arr, UINT64_MAX);

  s = call_sum_below(ctx, &u, 0);
  if (status("sum_below 0", s)) printf("%" PRIu64 "\n", u);
  s = call_sum_below(ctx, &u, 100);
  if (status("sum_below 100", s)) printf("%" PRIu64 "\n", u);
  s = call_sum_below(ctx, &u, 100000);
  if (status("sum_below 100000", s)) printf("%" PRIu64 "\n", u);

  int64_t k = 6;
  I64_CASE("apply 7", int64_t, call_apply, (void *)scale_thunk, &k, 7);
  I64_CASE("apply 1001", int64_t, call_apply, (void *)scale_thunk, &k, 1001);

  I64_CASE("positive 3", int64_t, call_positive, 3);
  I64_CASE("positive 0", int64_t, call_positive, 0);

  I64_CASE("choose true -128", int8_t, call_choose, 1, -128);
  I64_CASE("choose false 5", int8_t, call_choose, 0, 5);
  I64_CASE("choose false -128", int8_t, call_choose, 0, -128);

  /* 0.1 * 10 - 1 is exactly 2^-54 fused, but 0 with two roundings. */
  double d = 0;
  s = call_fused(ctx, &d, 0.1, 10.0, -1.0);
  if (status("fused", s)) printf("%a\n", d);

  hirsel_rt_v2_ctx_destroy(ctx);
  return 0;
}
